# Try cycle right shift: [A,B,C,D] → [D,A,B,C]
def build_cycled_output():
    result = []
    sep_rows = [0, 6, 7, 13, 14, 20, 21, 27, 28]

    for r in range(31):
        if r in sep_rows:
            result.append([0]*30)
            continue

        band_map = {
            'band1': [1,2,3,4,5],   # pattern: [3,2,2,3] -> cycle right: [3,3,2,2]
            'band2': [8,9,10,11,12], # pattern: [2,8,8,2] -> cycle right: [2,2,8,8]
            'band3': [15,16,17,18,19], # pattern: [3,2,2,3] -> cycle right: [3,3,2,2]
            'band4': [22,23,24,25,26], # pattern: [2,8,8,2] -> cycle right: [2,2,8,8]
            'band5': [29,30],        # border only
        }

        band_name = None
        for name, rows in band_map.items():
            if r in rows:
                band_name = name
                break

        block_colors = []
        if band_name == 'band1':
            block_colors = [3, 3, 2, 2]  # [3,2,2,3] cycled right: last→first = 3, then first three shifted
        elif band_name == 'band2':
            block_colors = [2, 2, 8, 8]  # [2,8,8,2] cycled right: 2,2,8,8
        elif band_name == 'band3':
            block_colors = [3, 3, 2, 2]
        elif band_name == 'band4':
            block_colors = [2, 2, 8, 8]
        else:
            block_colors = [4, 4, 4, 4]

        row_data = [0]*30
        row_data[29] = 4

        # Blocks at cols 1, 8, 15, 22
        for bc_idx, bc_col in enumerate([1, 8, 15, 22]):
            row_data[bc_col:bc_col+5] = [4, 4, 4, 4, 4]  # Borders
            row_data[bc_col+2:bc_col+4] = [block_colors[bc_idx]]*3  # Interior (cols +2 and +3)

        result.append(row_data)

    return result

output_cycle = build_cycled_output()
print("Cycled output (first 6 rows):")
for i, row in enumerate(output_cycle[:6]):
